css:
#glitch-wrapper {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  box-sizing: border-box;
}

#glitch-container {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  display: flex;
  justify-content: center;
  align-items: center;
  pointer-events: none;
  user-select: none;
  white-space: nowrap;
}

.glitch-layer {
  position: absolute;
  font-weight: 900;
  text-transform: uppercase;
  letter-spacing: 4px;
  text-align: center;
  transition: none;
}

#layer-main {
  color: #FFFFFF;
  z-index: 4;
}

#layer-red {
  color: #FF0055;
  mix-blend-mode: screen;
  z-index: 3;
  opacity: 0.85;
}

#layer-cyan {
  color: #00E5FF;
  mix-blend-mode: screen;
  z-index: 2;
  opacity: 0.85;
}

#layer-yellow {
  color: #FFE600;
  mix-blend-mode: screen;
  z-index: 1;
  opacity: 0.7;
}

render:
var p = ctx.progress;
var params = ctx.params;

var wrapper = ctx.root.querySelector('#glitch-wrapper');
var container = ctx.root.querySelector('#glitch-container');
var layerMain = ctx.root.querySelector('#layer-main');
var layerRed = ctx.root.querySelector('#layer-red');
var layerCyan = ctx.root.querySelector('#layer-cyan');
var layerYellow = ctx.root.querySelector('#layer-yellow');

if (!container || !wrapper) return;

// 1. Posicionamiento Global
container.style.left = params.pos_x + '%';
container.style.top = params.pos_y + '%';

var text = params.text_content || '';
var font = params.font_family || 'Impact, sans-serif';
var size = (params.font_size || 80) + 'px';

var layers = [layerMain, layerRed, layerCyan, layerYellow];
layers.forEach(function(l) {
  if (l) {
    l.textContent = text;
    l.style.fontFamily = font + ', sans-serif';
    l.style.fontSize = size;
  }
});

// 2. Expansión y Sacudida (Shake)
var startScale = 1.0;
var endScale = params.max_expansion_scale || 1.6;
var currentScale = startScale + (endScale - startScale) * p;

var shakeAmp = params.shake_intensity || 25;
var shakeX = (Math.sin(p * 143) + Math.cos(p * 293)) * shakeAmp * (0.4 + p * 0.6);
var shakeY = (Math.cos(p * 179) + Math.sin(p * 311)) * shakeAmp * (0.4 + p * 0.6);
var shakeRot = Math.sin(p * 97) * (shakeAmp * 0.25);

container.style.transform = 'translate(-50%, -50%) scale(' + currentScale + ') translate(' + shakeX + 'px, ' + shakeY + 'px) rotate(' + shakeRot + 'deg)';

// 3. Simulación de Motion Blur por la sacudida
var maxBlur = params.motion_blur_amount || 8;
var currentBlur = (Math.abs(shakeX) + Math.abs(shakeY)) / (shakeAmp * 2) * maxBlur * p;
container.style.filter = 'blur(' + currentBlur.toFixed(2) + 'px)';

// 4. Aberración Cromática (Capas RGB se separan)
var maxOffset = params.aberration_max_offset || 35;
var currentOffset = maxOffset * Math.pow(p, 1.2);

var redX = (Math.sin(p * 210) * 0.3 + 1) * currentOffset;
var redY = (Math.cos(p * 180) * 0.3 - 0.5) * currentOffset;

var cyanX = -(Math.cos(p * 250) * 0.3 + 1) * currentOffset;
var cyanY = -(Math.sin(p * 190) * 0.3 - 0.5) * currentOffset;

var yellowX = (Math.sin(p * 320)) * (currentOffset * 0.6);
var yellowY = (Math.cos(p * 340) + 1) * (currentOffset * 0.6);

if (layerRed) layerRed.style.transform = 'translate(' + redX + 'px, ' + redY + 'px)';
if (layerCyan) layerCyan.style.transform = 'translate(' + cyanX + 'px, ' + cyanY + 'px)';
if (layerYellow) layerYellow.style.transform = 'translate(' + yellowX + 'px, ' + yellowY + 'px)';

// 5. Paleta de Colores Estroboscópicos
var flashSpeed = params.flash_speed || 24;
var colorStep = Math.floor(p * flashSpeed);
var palette = [
  '#FFFFFF', // Blanco
  '#FF0055', // Magenta
  '#00E5FF', // Cyan
  '#FFE600', // Amarillo
  '#00FF66', // Verde Neón
  '#FF3300'  // Naranja
];
var currentColor = palette[colorStep % palette.length];
var altColor = palette[(colorStep + 3) % palette.length];

// 6. Lógica de Modos de Color (Texto vs Fondo)
var mode = params.flash_mode || 'Texto';
var staticBg = params.static_bg_color || '#0d0d0d';

if (mode === 'Texto') {
  wrapper.style.backgroundColor = staticBg;
  if (layerMain) layerMain.style.color = currentColor;
} else if (mode === 'Fondo') {
  wrapper.style.backgroundColor = currentColor;
  if (layerMain) layerMain.style.color = '#FFFFFF';
} else if (mode === 'Ambos (Alternado)') {
  wrapper.style.backgroundColor = currentColor;
  if (layerMain) layerMain.style.color = altColor;
}
